#!/usr/bin/env python3
"""Conan recipe for GNU Pth 2.0.7 - GNU Portable Threads.

Pth is a non-preemptive (cooperative) thread scheduler library that runs on
top of the POSIX threads / signals API.  It ships a library (libpth), a header
(pth.h) and the ``pth-config`` / ``pthread-config`` helper scripts.

OHOS notes
----------
* ``configure`` was generated by an old autoconf that hard-codes ``/tmp`` for
  its scratch parameter file; ``/tmp`` is read-only on OHOS, so the path is
  redirected to ``${TMPDIR:-/tmp}`` via a patch.
* ``config.sub`` (2005) does not know ``aarch64``.  Pth's machine-context code
  is method based (``mcsc`` = makecontext/swapcontext, ``sjlj`` =
  sigsetjmp/siglongjmp) and contains no aarch64 assembly, so the build is
  configured with the legacy-but-equivalent triplet ``arm-unknown-linux-gnu``
  to satisfy the ancient ``config.sub``.
* OHOS bionic does not provide ``makecontext``/``swapcontext``, so the ``sjlj``
  method with the ``sigaltstack`` stack setup is forced.
"""
import os

from conan import ConanFile
from conan.errors import ConanInvalidConfiguration
from conan.tools.files import (apply_conandata_patches, copy,
                               export_conandata_patches, get)
from conan.tools.layout import basic_layout

required_conan_version = ">=2.0"


class PthConan(ConanFile):
    name = "pth"
    version = "2.0.7"
    description = "GNU Portable Threads - cooperative (non-preemptive) threads"
    license = "LGPL-2.1-or-later"
    homepage = "https://www.gnu.org/software/pth/"
    url = ""

    package_type = "library"
    settings = "os", "compiler", "build_type", "arch"
    options = {"shared": [True, False], "fPIC": [True, False]}
    default_options = {"shared": False, "fPIC": True}

    def export_sources(self):
        export_conandata_patches(self)

    def validate(self):
        if self.settings.os not in ("Linux", "OHOS"):
            raise ConanInvalidConfiguration(
                "pth OHOS adaptation is validated on Linux/OHOS, not "
                + str(self.settings.os))

    def layout(self):
        basic_layout(self)

    def source(self):
        get(self, **self.conan_data["sources"], strip_root=True)

    def _compiler(self, name, fallback):
        executables = self.conf.get(
            "tools.build:compiler_executables", default={}, check_type=dict) or {}
        return executables.get(name) or fallback

    def build(self):
        apply_conandata_patches(self)
        # The generated config.status creates its scratch directory with
        # `umask 077 && mktemp -d` (mode 0700).  On the OHOS shared filesystem
        # (HMDFS, setgid parent) a 0700 directory is not writable, and mktemp
        # always creates 0700 regardless of umask, so config.status fails with
        # "Permission denied" while writing its temporary files.  Follow the
        # knowledge base (E011 / DRAFT-6507-cln-mktemp-0700-hmdfs): drop mktemp
        # and create the scratch directory with `umask 000 && mkdir`, so the
        # mode is decided at creation time.
        configure_path = os.path.join(self.source_folder, "configure")
        with open(configure_path, "r") as handle:
            content = handle.read()
        old = '  tmp=`(umask 077 && mktemp -d -q "./confstatXXXXXX") 2>/dev/null` &&'
        new = '  tmp=./confstat$$-$RANDOM; (umask 000 && mkdir "$tmp") &&'
        content = content.replace(old, new)
        with open(configure_path, "w") as handle:
            handle.write(content)

        cc = self._compiler("c", "clang")
        cxx = self._compiler("cpp", "clang++")
        shared = "--enable-shared" if self.options.shared else "--disable-shared"
        args = [
            "--host=arm-unknown-linux-gnu",
            "--build=arm-unknown-linux-gnu",
            shared,
            "--enable-static",
            "--with-mctx-mth=sjlj",
            "--with-mctx-dsp=sjlje",
            "--with-mctx-stk=sas",
            "--prefix=%s" % self.package_folder,
        ]
        self.run('CC="{}" CXX="{}" ./configure {}'.format(
            cc, cxx, " ".join(args)), cwd=self.source_folder)
        self.run("make", cwd=self.source_folder)
        # Run the upstream test suite on the target.
        # `make test` runs test_std (global library API / basic / nested thread
        # operations) - self-contained and assertion based.
        self.run("timeout 300 make test", cwd=self.source_folder)
        # test_mp / test_misc are interactive demos that terminate on stdin EOF
        # ("Enter quit"/"Enter q"); feed /dev/null so they reach EOF and exit
        # instead of blocking on input in the non-interactive CI sandbox.
        self.run("timeout 300 make test-mp test-misc < /dev/null",
                 cwd=self.source_folder)
        # Exempted upstream programs (reasons recorded in PR body / MANIFEST):
        #   test_sig     - interactive (SRC: "user has to hit CTRL-C three times")
        #   test_select  - loops forever by design (never returns)
        #   test_httpd   - requires a running network server
        #   test_pthread - fails to compile in this (sjlj) configuration
        #   test_sfio    - not configured with --with-sfio, only prints a notice
        #   test_uctx    - performance benchmark (10,000,000 context switches;
        #                  "be patient!"), not an assertion test
        #   test_philo   - 60 s observation demo of the dining philosophers,
        #                  no assertions

    def package(self):
        copy(self, "COPYING",
             src=self.source_folder,
             dst=os.path.join(self.package_folder, "licenses"))
        copy(self, "pth.h",
             src=os.path.join(self.source_folder),
             dst=os.path.join(self.package_folder, "include"))
        copy(self, "pthread.h",
             src=os.path.join(self.source_folder),
             dst=os.path.join(self.package_folder, "include"))
        copy(self, "*.a",
             src=os.path.join(self.source_folder, ".libs"),
             dst=os.path.join(self.package_folder, "lib"), keep_path=False)
        copy(self, "*.so*",
             src=os.path.join(self.source_folder, ".libs"),
             dst=os.path.join(self.package_folder, "lib"), keep_path=False)
        copy(self, "pth-config",
             src=self.source_folder,
             dst=os.path.join(self.package_folder, "bin"))

    def package_info(self):
        self.cpp_info.libs = ["pth"]
        if self.settings.os == "Linux":
            self.cpp_info.system_libs = ["dl", "m"]
